struct zcr_extended_text_input_v1_listener {
	/**
	 * set preedit from the surrounding text
	 *
	 * IME requests to update text_input client to set the preedit
	 * from the surrounding text.
	 *
	 * index is the starting point of the preedit, relative to the
	 * current cursor position in utf-8 byte-offset. length is the
	 * length of the preedit region in utf-8 byte length.
	 *
	 * Following the convention we have in text_input::preedit_string,
	 * text_input::preedit_styling sent just before this will be
	 * applied.
	 */
	void (*set_preedit_region)(void *data,
				   struct zcr_extended_text_input_v1 *zcr_extended_text_input_v1,
				   int32_t index,
				   uint32_t length);
	/**
	 * clear grammar fragments in a range
	 *
	 * IME requests to clear all the grammar markers within the given
	 * range defined by start and end.
	 *
	 * start and end are relative to the beginning of the input field
	 * in utf-8 byte length.
	 * @since 3
	 */
	void (*clear_grammar_fragments)(void *data,
					struct zcr_extended_text_input_v1 *zcr_extended_text_input_v1,
					uint32_t start,
					uint32_t end);
	/**
	 * add grammar fragment
	 *
	 * IME requests to add a new grammar fragment.
	 *
	 * A grammar fragment describes a range of text (start, end) that
	 * has grammar error and also gives the correct replacement text.
	 * It is expected that the renderer will render markers (e.g.
	 * squigles or dashed underlines) under the text to notify users
	 * that there is a grammar error. It is also expected that the
	 * renderer will maintain and update the position of fragment when
	 * users edit other parts of the text, e.g. if users type something
	 * before the grammar fragment, the marker should move accordingly.
	 *
	 * start and end are relative to the beginning of the input field
	 * in utf-8 byte length. suggestion is the correct replacement
	 * text, encoded in utf-8 and suggested by ML model.
	 * @since 3
	 */
	void (*add_grammar_fragment)(void *data,
				     struct zcr_extended_text_input_v1 *zcr_extended_text_input_v1,
				     uint32_t start,
				     uint32_t end,
				     const char *suggestion);
	/**
	 * set autocorrect range
	 *
	 * IME requests to update text_input client to set the
	 * autocorrect range. There is only one autocorrect range, so this
	 * replaces any existing autocorrect ranges.
	 *
	 * start and end are relative to the beginning of the input field
	 * in utf-8 byte length.
	 *
	 * If start and end are the same, then the autocorrect range is
	 * cleared.
	 * @since 4
	 */
	void (*set_autocorrect_range)(void *data,
				      struct zcr_extended_text_input_v1 *zcr_extended_text_input_v1,
				      uint32_t start,
				      uint32_t end);
	/**
	 * Sets the virtual keyboard's occluded bounds.
	 *
	 * This event tells the client about the part of the virtual
	 * keyboard's bounds that occludes the text input's window, in
	 * screen DIP coordinates. In order for the text input to make
	 * proper use of this information, it needs to know its window's
	 * screen DIP bounds via another interface such as the aura-shell.
	 *
	 * The occluded bounds may be smaller than the keyboard's visual
	 * bounds.
	 *
	 * When the virtual keyboard is hidden or floating, empty bounds
	 * are sent, i.e. with zero width and height.
	 * @since 5
	 */
	void (*set_virtual_keyboard_occluded_bounds)(void *data,
						     struct zcr_extended_text_input_v1 *zcr_extended_text_input_v1,
						     int32_t x,
						     int32_t y,
						     int32_t width,
						     int32_t height);
	/**
	 * Commits the current preedit
	 *
	 * Commits the current preedit and modify the selection range
	 * according to selection_behavior. Has no effect if there's no
	 * preedit text.
	 * @since 11
	 */
	void (*confirm_preedit)(void *data,
				struct zcr_extended_text_input_v1 *zcr_extended_text_input_v1,
				uint32_t selection_behavior);
	/**
	 * Inserts image
	 *
	 * This inserts a given image into current editing field. The
	 * value of src should be a valid http(s) URL pointing to some
	 * image.
	 *
	 * Note: this only works for richly-editable editing field in web
	 * apps. Internally it sends a PasteFromImage editing command to
	 * blink engine. If the current editing field is not
	 * richly-editable, this event will be ignored.
	 * @since 13
	 */
	void (*insert_image)(void *data,
			     struct zcr_extended_text_input_v1 *zcr_extended_text_input_v1,
			     const char *src);
};

