zcr_extended_text_input_v1_set_large_surrounding_text(struct zcr_extended_text_input_v1 *zcr_extended_text_input_v1, int32_t text, uint32_t size, uint32_t cursor, uint32_t anchor)
{
	wl_proxy_marshal_flags((struct wl_proxy *) zcr_extended_text_input_v1,
			 ZCR_EXTENDED_TEXT_INPUT_V1_SET_LARGE_SURROUNDING_TEXT, NULL, wl_proxy_get_version((struct wl_proxy *) zcr_extended_text_input_v1), 0, text, size, cursor, anchor);
}

